/**
 * Standalone entry point for generating the Custom Elements Manifest.
 *
 * In normal use the manifest is generated by the Lume `afterBuild` hook in
 * `_config.ts` (which also handles brotli compression and the service-worker
 * file tree). This task exists for regenerating the manifest on its own, e.g.
 * while iterating on element JSDoc without running a full build.
 */
import { generateManifest } from "./cem.js";

const ROOT = import.meta.dirname + "/..";

await generateManifest(ROOT);
